import datetime,json,pathlib,subprocess
S=pathlib.Path('/var/lib/kubiq-mongodb')
def kub(*args):return subprocess.check_output(['k3s','kubectl',*args],text=True)
def obj(*args):return json.loads(kub(*args,'-o','json'))
state=obj('get','statefulset','mongodb','-n','mongodb-system');assert state['status'].get('readyReplicas')==1
pvc=obj('get','pvc','data-mongodb-0','-n','mongodb-system');pv=obj('get','pv',pvc['spec']['volumeName']);assert pv['spec']['persistentVolumeReclaimPolicy']=='Retain'
server=json.loads(kub('exec','-n','mongodb-system','mongodb-migration','--','env','HOME=/work','mongosh','--nodb','--norc','--quiet','/work/operations/admin-control.js').splitlines()[-1]);assert server['ttlMonitorEnabled'] is True
live=json.loads(kub('exec','-n','kubiq-system','deployment/kubiq','--','node','-e',"console.log(JSON.stringify({productionStillUsesAtlas:process.env.DB_URI.startsWith('mongodb+srv://')}))"));assert live['productionStillUsesAtlas']
pods=obj('get','pods','-A')['items'];running=[p for p in pods if p.get('status',{}).get('phase')=='Running'];restarts=sum(c.get('restartCount',0) for p in running for c in p.get('status',{}).get('containerStatuses',[]));assert restarts==0
flux=obj('get','kustomizations','-n','flux-system')['items'];assert all(any(c['type']=='Ready' and c['status']=='True' for c in x['status']['conditions']) for x in flux)
backup=json.loads((S/'last-backup.json').read_text());assert backup.get('restoreTested') and backup.get('restoreFixtureRemoved')
report={'collectedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'mongodb':{'namespace':'mongodb-system','version':server['version'],'ready':True,'persistentAfterRestart':True,'cpuRequest':'100m','cpuLimit':'500m','memoryRequest':'512Mi','memoryLimit':'768Mi','pvc':'10Gi','pvReclaimPolicy':'Retain','privateClusterIpOnly':True,'usingPerCpuCaches':server.get('usingPerCpuCaches'),'ttlEnabled':server['ttlMonitorEnabled']},'rehearsal':json.loads((S/'rehearsal-verification.json').read_text()),'auth':json.loads((S/'auth-verification.json').read_text()),'adapters':json.loads((S/'adapter-verification.json').read_text()),'backup':backup,'atlasRehearsalArchive':json.loads((S/'atlas-rehearsal-archive.json').read_text()),'networkPolicyUnrelatedNamespaceBlocked':True,'backupIdentityOutsidePrefixDenied':True,'productionStillUsesAtlas':True,'finalCutoverPerformed':False,'runtimeSecretAndApplicationImageUnchanged':True,'runningContainerRestarts':restarts,'fluxKustomizationsReady':True}
(S/'installation-verification.json').write_text(json.dumps(report,indent=2));print(json.dumps({'verificationPassed':True,'collections':len(report['rehearsal']['collections']),'documents':report['rehearsal']['totalDocuments'],'productionStillUsesAtlas':True,'backupRestoredFromGcs':True}))
